def _poser_decor(c, x0, y0):
    """Grave le dessin UNE FOIS par document, puis le tamponne.
    ⚠️ Aucune couleur n'est posée dans le tampon : il prend celle du
    carton, donc le même tampon sert aux dix couleurs de l'arc-en-ciel.
    ⚠️⚠️ La marque est posée SUR LE CANEVAS (getattr), jamais dans un
    dictionnaire indexé par id() : Python réutilise les id() libérés, et
    le deuxième document croirait le tampon déjà gravé — le PDF sortirait
    cassé. C'est la méthode de AHE, MAKEMO, DRAGON D'OR et AREAREA."""
    nom = "TRIO75_DECOR"
    if not getattr(c, "_t75_forme_faite", False):
        c.beginForm(nom, lowerx=0, lowery=0, upperx=CARD_W, uppery=CARD_H)
        p = c.beginPath()
        for contour in _DECOR.split("|"):
            i = 0
            n = len(contour)
            while i < n:
                cmd = contour[i]
                j = i + 1
                while j < n and contour[j] not in "mlc":
                    j += 1
                v = [float(x) for x in contour[i + 1:j].split(",")]
                if cmd == "m":
                    p.moveTo(v[0] / 1000.0 * CARD_W, CARD_H - v[1] / 1000.0 * CARD_H)
                elif cmd == "l":
                    p.lineTo(v[0] / 1000.0 * CARD_W, CARD_H - v[1] / 1000.0 * CARD_H)
                else:
                    p.curveTo(v[0] / 1000.0 * CARD_W, CARD_H - v[1] / 1000.0 * CARD_H,
                              v[2] / 1000.0 * CARD_W, CARD_H - v[3] / 1000.0 * CARD_H,
                              v[4] / 1000.0 * CARD_W, CARD_H - v[5] / 1000.0 * CARD_H)
                i = j
            p.close()
        c.drawPath(p, stroke=0, fill=1)
        c.endForm()
        c._t75_forme_faite = True
    c.saveState()
    c.translate(x0, y0)
    c.doForm(nom)
    c.restoreState()


def _gen_carte(rng):
    """Les CINQ rangées de la carte, sans un seul doublon.

    ⚠️⚠️ RÈGLE MARATHON : on tire d'abord, pour CHAQUE plage, les 15
    numéros de la carte entière (5 rangées × 3) — d'un seul coup, avec
    `sample`, qui ne rend jamais deux fois le même. On les distribue
    ensuite entre les rangées. Tirer rangée par rangée aurait laissé
    passer des doublons d'une rangée à l'autre.
    """
    grilles = [[] for _ in range(NB_GRILLES)]
    for pmin, pmax in PLAGES:
        besoin = NB_GRILLES * NB_PAR_PLAGE
        tous = rng.sample(range(pmin, pmax + 1), besoin)
        for g in range(NB_GRILLES):
            grilles[g].append(sorted(tous[g * NB_PAR_PLAGE:(g + 1) * NB_PAR_PLAGE]))
    return grilles


# ══ LA TAILLE DES CHIFFRES ═══════════════════════════════════════════
# ⚡ LE TRIO SE LIT COMME SUR SON MODÈLE (sceau Maeva 12/08, gardé) :
#    DEUX numéros en haut, LE TROISIÈME dessous, centré entre les deux.
# ⚠️ Tailles MESURÉES à 600 dpi, chaque valeur de chaque plage imprimée
#    dans sa case, pixels de contact comptés contre les traits de sa
#    grille. Voir le LIS_MOI livré avec le fichier.
_T_HAUT = 38.0        # les deux du haut
_T_BAS = 33.0         # celui du bas
_MARGE = 1.1 * mm     # blanc gardé en haut et en bas de la case
_ECART = 0.9 * mm     # blanc gardé ENTRE les deux étages
# ⚠️⚠️ C'EST LA HAUTEUR QUI COMMANDE, PAS LA LARGEUR. Sa plus petite case
#    fait 37,74 x 21,53 mm. En hauteur il reste 52,2 pt pour les deux
#    étages une fois les blancs gardés ; 38 + 33 en demandent 51,1 —
#    ça passe. 40 + 35 en demanderaient 54,0 : ça ne passe pas.
#    En largeur il y a tout l'aise du monde (38 pt pour 50 disponibles).
# ⚠️ Les étages sont calés sur des repères FIXES de la case, pas sur une
#    formule qui glisse avec la taille : c'est ce qui garantit qu'ils ne
#    se rejoignent jamais quand on change les tailles.


def _etages(haut, bas):
    """Les deux lignes de base, dans une case allant de `bas` à `haut`.
    Le bloc des deux étages est CENTRÉ dans la case : ses rangées ne font
    pas toutes la même hauteur et on ne corrige pas sa main."""
    bloc = 0.72 * (_T_HAUT + _T_BAS) + _ECART
    sommet = haut - (haut - bas - bloc) / 2.0
    base_haut = sommet - 0.72 * _T_HAUT
    base_bas = base_haut - _ECART - 0.72 * _T_BAS
    return base_haut, base_bas


def _dessiner_carte(c, x0, y0, grilles, couleur_hex, serie, titre_jeu="",
                    telephone="", style="eco", evenement_id=""):
    police_ch, gris_ch = _style_chiffres(style)
    col = colors.HexColor(couleur_hex)

    # 1) SA PLANCHE, telle quelle
    c.setFillColor(col)
    _poser_decor(c, x0, y0)

    # 2) les chiffres dans ses cases
    def _mx(v):   # millièmes -> x réel
        return x0 + v / 1000.0 * CARD_W

    def _my(v):   # millièmes (0 en haut) -> y réel
        return y0 + CARD_H - v / 1000.0 * CARD_H

    c.setFillColor(gris_ch)
    for gi, grille in enumerate(grilles):
        haut = _my(ROWS[gi])
        bas = _my(ROWS[gi + 1])
        for pi, nums in enumerate(grille):
            g = _mx(COLS[pi])
            d = _mx(COLS[pi + 1])
            larg = d - g
            y_haut, y_bas = _etages(haut, bas)
            # étage du haut : deux numéros, chacun sur sa moitié
            c.setFont(police_ch, _T_HAUT)
            c.drawCentredString(g + larg * 0.27, y_haut, str(nums[0]))
            c.drawCentredString(g + larg * 0.73, y_haut, str(nums[1]))
            # étage du bas : le troisième, seul et centré
            c.setFont(police_ch, _T_BAS)
            c.drawCentredString(g + larg * 0.50, y_bas, str(nums[2]))

    # 3) le numéro de série, dans la bande blanche sous la grille
    #    ⚠️ 1,62 mm de haut : c'est la seule place libre de sa planche.
    c.setFillColor(GRIS)
    c.setFont(POLICE, 4.5)
    c.drawString(_mx(COLS[0]) + 1.2 * mm, _my(BANDE_Y), "N° %06d" % serie)
    bas = ""
    if titre_jeu and "TRIO 75" not in titre_jeu.strip().upper():
        bas = titre_jeu.strip()
    if telephone:
        bas = (bas + "  ·  " if bas else "") + telephone
    if bas:
        c.drawRightString(_mx(COLS[5]) - 1.2 * mm, _my(BANDE_Y), bas[:58])

    # 4) le cadre de microtexte anti-photocopie
    if _sec:
        try:
            _sec.cadre_micro(c, x0, y0, CARD_W, CARD_H, serie, retrait=1.2 * mm)
        except Exception:
            pass


def generer_pdf(nb_cartes=10, serie_start=1, theme="", couleur=True,
                nom_evenement="", titre_jeu="", couleur_perso="", date_lieu="",
                telephone="", style="eco", evenement_id="", page_start=1):
    buf = io.BytesIO()
    c = canvas.Canvas(buf, pagesize=A4, pageCompression=1)

    nb_cartes = max(1, min(int(nb_cartes), 10000))
    nb_pages = (nb_cartes + ROWS_PAGE - 1) // ROWS_PAGE

    rng = random.Random(945000 + int(serie_start))
    serie = int(serie_start)
    no_page = max(1, int(page_start))
    faites = 0

    for _ in range(nb_pages):
        if nom_evenement:
            c.setFillColor(colors.black); c.setFont(POLICE, 9)
            c.drawCentredString(PAGE_W / 2, PAGE_H - 5 * mm, nom_evenement)
        c.setFillColor(GRIS_CLAIR); c.setFont(POLICE, 6)
        c.drawCentredString(PAGE_W / 2, PAGE_H - 7.2 * mm, "%03d" % no_page)

        for row in range(ROWS_PAGE):
            if faites >= nb_cartes:
                break
            x0 = MARGIN_X
            y0 = MARGIN_BOT + (ROWS_PAGE - 1 - row) * (CARD_H + GUTTER_Y)
            grilles = _gen_carte(rng)
            coul = (couleur_perso if (couleur and couleur_perso)
                    else RAINBOW[(serie - 1) % len(RAINBOW)] if couleur else "#555555")
            _dessiner_carte(c, x0, y0, grilles, coul, serie, titre_jeu, telephone,
                            style=style, evenement_id=evenement_id)
            serie += 1
            faites += 1

        c.showPage()
        no_page += 1

    c.save()
    buf.seek(0)
    return buf


if __name__ == "__main__":
    pdf = generer_pdf(nb_cartes=4, couleur=False)
    with open("test_trio75.pdf", "wb") as f:
        f.write(pdf.read())
    print("TRIO 75 genere")
